-- Comprobacion: total, slugs distintos y lugares sin score (esperado 0).
SELECT COUNT(*) AS lugares, COUNT(DISTINCT slug) AS slugs, SUM(score IS NULL) AS sin_score
FROM `nexus`.`places`;
